head.script:
///////// 2. 초기화 영역 /////////
            scwin.onpageload = function() {

                scwin.vScrenID = "ULDTMS03010.xml";
///////// 1. 변수 및 선언 영역 /////////
scwin.pageId = "ULDTMS03010";
scwin.scrollTop = "";
                // 상장고시 시장구분코드, 서식관리 기관 구분코드, 보고서 본문 구분코드
                const list = ["LD_MKT_TP_CD", "FORM_ADM_INST_TP_CD", "WRTRPT_MAINDOC_TP_CD"];
                const params = {"cdEngNmList":list};

                // 코드 정보 조회
                $c.sbm.execute(sbm_code, params);

                // 초기화
                pgl_list.hide();
            };

///////// 3. 컴포넌트 이벤트 영역 /////////
            scwin.btn_search_onclick = function (e) {

                scwin.fnSearch("Y", 1);
            };

            scwin.sbx_page_onchange = function (info) {

                scwin.fnSearch("Y", 1);
            };

            scwin.pgl_list_onclick = function (index) {

                scwin.fnSearch("N", index);
            };

// Excel 다운로드
            scwin.btn_excel_onclick = function (e) {

                // 파라미터 처리
                const url = "/api/form/formInfo/excel";
                $c.tms.downloadProc(url, dma_search.getJSON());                
            };

// Word 다운로드
            scwin.btn_word_onclick = function (e) {

                let data1 = "";
                let data2 = "";
                for (let i=0; i < dlt_list.getRowCount(); i++) {
                    if (dlt_list.getCellData(i, "CHK")) {
                        data1 += dlt_list.getCellData(i, "formCd") + ",";
                        data2 += dlt_list.getCellData(i, "formVer") + ",";                        
                    }
                }

                if (data1 !== "") {
                    data1 = data1.substring(0, data1.length - 1);
                    data2 = data2.substring(0, data2.length - 1);
                    // 파라미터 처리
                    let params = {};
                    params.formCd = data1;
                    params.formVer = data2;

                    const url = "/api/form/formInfo/word";
                    $c.tms.downloadProc(url, params);                    
                } else {
                    $c.win.alert("다운로드 할 서식을 체크해 주세요.");
                }
            };

// 상세 조회            
            scwin.grd_list_oncellclick = function (rowIndex, columnIndex, columnId) {

                // 서식명일 경우 상세 조회
                if (columnId === "formKorNm") {                
                    const url_ = "/ui/TMS/ULDTMS03020.xml";

                    // 조회 조건 임시 저장
                    $c.tms.setKeywordSave(scwin.pageId, grd_list, dma_search);

                    // 페이지 이동
                    const params = {};
                    params.storageId = scwin.pageId;
                    params.formCd = grd_list.getCellData(rowIndex, "formCd");
                    params.formVer = grd_list.getCellData(rowIndex, "formVer");

                    $c.win.moveUrl(url_, params);
                }
            };

// 등록 페이지 이동 
            scwin.btn_insert_onclick = function (e) {

                const url_ = "/ui/TMS/ULDTMS03120.xml";

                // 조회 조건 임시 저장
                $c.tms.setKeywordSave(scwin.pageId, grd_list, dma_search);

                // 페이지 이동
                const params = {};
                params.storageId = scwin.pageId;
                $c.win.moveUrl(url_, params);
            };

            scwin.ibx_searchCont_onkeyup = function (e) {

                if (e.key === "Enter") {                    
                    scwin.fnSearch("Y", 1);
                }                
            };

///////// 4. 서브미션 콜백 영역 /////////
            scwin.sbm_code_submitdone = function (e) {

                // 조회 성공인 경우
                const result = e.responseJSON;
                if (result.success) {                    
                    // radio box 자동 생성
                    $c.tms.setSelectData(result.body, rdo_ldMktTpCd, "cdValNm", "cdVal", "LD_MKT_TP_CD", "cdEngNm");
                    $c.tms.setSelectData(result.body, rdo_formAdmInstTpCd, "cdValNm", "cdVal", "FORM_ADM_INST_TP_CD", "cdEngNm");
                    $c.tms.setSelectData(result.body, rdo_wrtrptMaindocTpCd, "cdValNm", "cdVal", "WRTRPT_MAINDOC_TP_CD", "cdEngNm");                               
                } else {
                    $c.win.alert(result.message);
                }

                // 시간의 Term이 생겨서 약간의 Term에 처리
                setTimeout(function () {
                    const storageId = $c.data.getParameter("storageId");
                    if (!$c.util.isEmpty(storageId)) {                    
                        scwin.scrollTop = $c.tms.getKeywordSave(storageId, dma_search) 

                        if (dma_search.get("page") !== "") {
                            scwin.fnSearch("Y", dma_search.get("page"));
                        }                    
                    }
                }, 100);
            };

            scwin.sbm_list_submitdone = function (e) {

                // 조회 성공인 경우
                const result = e.responseJSON;
                if (result.success) {
                    const obj = result.body;

                    const firstYn = dma_search.get("totalYn");
                    let totalCnt = 0;

                    // 최초 조회일 경우에만 전체 건수를 구하여 전역변수에 담는다.
                    if (firstYn === "Y") {
                        if (!$c.util.isEmpty(obj.totalCount)) {
                            tbx_totCnt.setValue($c.num.formatNumber(obj.totalCount));
                            totalCnt = parseInt(obj.totalCount) || 0;
                        }        

                        // 데이터가 있는 경우에만 페이지 리스트 표시
                        if (totalCnt > 0) { 
                            pgl_list.setCount(obj.totalPages);
                            pgl_list.show();
                        } else {
                            pgl_list.hide();
                        }            
                    }

                    // 재조회 여부 체크
                    if (!$c.util.isEmpty(scwin.scrollTop)) {
                        grd_list.setScrollTop(scwin.scrollTop);                        
                        scwin.scrollTop = "";
                    }
                } else {
                    $c.win.alert(result.message);
                }               
            };

///////// 5. 일반/업무 함수 영역 /////////
            /*
             * @method
             * @name fnSearch
             * @description 
             * 조회 
             * @param {String} totYn 총 건수 조회여부
             * @param {Numer} index 조회할 데이터의 시작 idx             
             */
            scwin.fnSearch = function (totYn, index) {

                dma_search.set("totalYn", totYn);
                dma_search.set("page", index);
                dma_search.set("size", sbx_page.getValue());

                // 조회 
                $c.sbm.execute(sbm_list, dma_search.getJSON());
            };

/*
 * @method
 * @name fnFormKorNmHtml
 * @description
 * 그리드(사용유무) 결과 변경
 * @param {String} data 데이타
 * @param {String} formattedData 포맷 데이타
 * @param {int} rowIndex row 위치
 * @param {int} columnIndex col 위치
 */
            scwin.fnFormKorNmHtml = function (data, formattedData, rowIndex, columnIndex) {

                if (dlt_list.getCellData(rowIndex, "useYn") === "N") {
                    grd_list.setCellClass(rowIndex, "formKorNm", "invalid");
                    //grd_list.setCellClass(rowIndex, 2, "invalid");
                    grd_list.setRowColor(rowIndex, "#E3E3E3");
                    data = "<span style='background-color:#FCBE8C;color:#FF5E17'>폐지</span> " + data;                    
                }                
                return data;

            };

/*
 * @method
 * @name fnRepFormVerYnHtml
 * @description
 * 그리드(대표유무) 결과 변경
 * @param {String} data 데이타
 * @param {String} formattedData 포맷 데이타
 * @param {int} rowIndex row 위치
 * @param {int} columnIndex col 위치
 */
            scwin.fnRepFormVerYnHtml = function (data, formattedData, rowIndex, columnIndex) {

                if (data === "Y") {
                    data = "<span style='background-color:#D4FBCE;color:#1EBA0C'>예</span>";                
                } else {
                    data = "<span style='background-color:#D4D4D4;'>아니오</span>";
                }            
                return data
            };

/*
 * @method
 * @name fnUseYnHtml
 * @description
 * 그리드(사용유무) 결과 변경
 * @param {String} data 데이타
 * @param {String} formattedData 포맷 데이타
 * @param {int} rowIndex row 위치
 * @param {int} columnIndex col 위치
 */
            scwin.fnUseYnHtml = function (data, formattedData, rowIndex, columnIndex) {

                if (data === "Y") {
                    data = "<span style='background-color:#D4FBCE;color:#1EBA0C'>예</span>";                
                } else {
                    data = "<span style='background-color:#D4D4D4;'>아니오</span>";
                }            
                return data
            };
